/**
 * CommandServer.js
 * Remote command and control module with message routing
 * Enables bidirectional communication for distributed red team operations
 */

export class CommandServer {
  constructor(config = {}) {
    this.config = {
      serverUrl: config.serverUrl || 'ws://localhost:8080',
      reconnectInterval: config.reconnectInterval || 3000,
      maxReconnectAttempts: config.maxReconnectAttempts || 5,
      clientId: config.clientId || this._generateClientId(),
      heartbeatInterval: config.heartbeatInterval || 30000,
      ...config
    };

    this.ws = null;
    this.reconnectAttempts = 0;
    this.connected = false;
    this.messageQueue = [];
    this.handlers = new Map();
    this.requestCallbacks = new Map();
    this.requestIdCounter = 0;
    this.heartbeatTimer = null;

    this._setupDefaultHandlers();
  }

  /**
   * Connect to the command server
   */
  connect() {
    return new Promise((resolve, reject) => {
      try {
        this.ws = new WebSocket(this.config.serverUrl);

        this.ws.onopen = () => {
          console.log('[CommandServer] Connected to server');
          this.connected = true;
          this.reconnectAttempts = 0;
          this._startHeartbeat();
          this._flushMessageQueue();
          resolve();
        };

        this.ws.onmessage = (event) => {
          this._handleMessage(event.data);
        };

        this.ws.onerror = (error) => {
          console.error('[CommandServer] WebSocket error:', error);
          reject(error);
        };

        this.ws.onclose = () => {
          console.log('[CommandServer] Disconnected from server');
          this.connected = false;
          this._stopHeartbeat();
          this._attemptReconnect();
        };
      } catch (error) {
        reject(error);
      }
    });
  }

  /**
   * Disconnect from the command server
   */
  disconnect() {
    if (this.ws) {
      this.connected = false;
      this._stopHeartbeat();
      this.ws.close();
      this.ws = null;
    }
  }

  /**
   * Send a command to the server
   * @param {string} command - Command type
   * @param {object} payload - Command payload
   * @param {boolean} expectsResponse - Whether to wait for response
   */
  async sendCommand(command, payload = {}, expectsResponse = false) {
    const message = {
      type: 'command',
      command,
      payload,
      clientId: this.config.clientId,
      timestamp: Date.now()
    };

    if (expectsResponse) {
      message.requestId = ++this.requestIdCounter;
      return new Promise((resolve, reject) => {
        this.requestCallbacks.set(message.requestId, { resolve, reject, timeout: setTimeout(() => {
          this.requestCallbacks.delete(message.requestId);
          reject(new Error(`Command '${command}' timed out`));
        }, 30000) });
        this._sendMessage(message);
      });
    }

    this._sendMessage(message);
  }

  /**
   * Send telemetry/data to the server
   * @param {object} data - Telemetry data
   */
  sendTelemetry(data) {
    const message = {
      type: 'telemetry',
      data,
      clientId: this.config.clientId,
      timestamp: Date.now()
    };
    this._sendMessage(message);
  }

  /**
   * Register a command handler
   * @param {string} command - Command to handle
   * @param {function} callback - Handler function
   */
  onCommand(command, callback) {
    if (!this.handlers.has(command)) {
      this.handlers.set(command, []);
    }
    this.handlers.get(command).push(callback);
  }

  /**
   * Route a message to a specific target
   * @param {string} targetClientId - Target client ID
   * @param {object} data - Message data
   */
  routeMessage(targetClientId, data) {
    const message = {
      type: 'route',
      targetClientId,
      data,
      fromClientId: this.config.clientId,
      timestamp: Date.now()
    };
    this._sendMessage(message);
  }

  /**
   * Broadcast a message to all connected clients
   * @param {object} data - Message data
   */
  broadcastMessage(data) {
    const message = {
      type: 'broadcast',
      data,
      fromClientId: this.config.clientId,
      timestamp: Date.now()
    };
    this._sendMessage(message);
  }

  /**
   * Get client information
   */
  getClientInfo() {
    return {
      clientId: this.config.clientId,
      connected: this.connected,
      userAgent: navigator.userAgent,
      url: window.location.href,
      timestamp: Date.now()
    };
  }

  /**
   * Handle incoming message
   * @private
   */
  _handleMessage(data) {
    try {
      const message = typeof data === 'string' ? JSON.parse(data) : data;

      // Handle response to a request
      if (message.requestId && this.requestCallbacks.has(message.requestId)) {
        const callback = this.requestCallbacks.get(message.requestId);
        clearTimeout(callback.timeout);
        this.requestCallbacks.delete(message.requestId);

        if (message.error) {
          callback.reject(new Error(message.error));
        } else {
          callback.resolve(message.response);
        }
        return;
      }

      // Handle routed messages
      if (message.type === 'route' && message.targetClientId === this.config.clientId) {
        this._dispatchEvent('message', message.data);
        return;
      }

      // Handle broadcast messages
      if (message.type === 'broadcast') {
        this._dispatchEvent('broadcast', message.data);
        return;
      }

      // Handle commands
      if (message.type === 'command') {
        this._executeCommand(message.command, message.payload, message.requestId);
        return;
      }

      this._dispatchEvent('message', message);
    } catch (error) {
      console.error('[CommandServer] Error handling message:', error);
    }
  }

  /**
   * Execute a command locally
   * @private
   */
  async _executeCommand(command, payload, requestId) {
    try {
      const handlers = this.handlers.get(command) || [];
      let result = null;

      for (const handler of handlers) {
        result = await handler(payload);
      }

      if (requestId) {
        this._sendMessage({
          type: 'response',
          requestId,
          response: result,
          clientId: this.config.clientId,
          timestamp: Date.now()
        });
      }
    } catch (error) {
      console.error(`[CommandServer] Error executing command '${command}':`, error);
      if (requestId) {
        this._sendMessage({
          type: 'response',
          requestId,
          error: error.message,
          clientId: this.config.clientId,
          timestamp: Date.now()
        });
      }
    }
  }

  /**
   * Send a message through the WebSocket
   * @private
   */
  _sendMessage(message) {
    if (this.connected && this.ws && this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify(message));
    } else {
      this.messageQueue.push(message);
    }
  }

  /**
   * Flush queued messages
   * @private
   */
  _flushMessageQueue() {
    while (this.messageQueue.length > 0) {
      const message = this.messageQueue.shift();
      this._sendMessage(message);
    }
  }

  /**
   * Attempt to reconnect to the server
   * @private
   */
  _attemptReconnect() {
    if (this.reconnectAttempts >= this.config.maxReconnectAttempts) {
      console.error('[CommandServer] Max reconnection attempts reached');
      return;
    }

    this.reconnectAttempts++;
    console.log(`[CommandServer] Reconnecting... (attempt ${this.reconnectAttempts})`);

    setTimeout(() => {
      this.connect().catch(() => {
        this._attemptReconnect();
      });
    }, this.config.reconnectInterval);
  }

  /**
   * Start heartbeat mechanism
   * @private
   */
  _startHeartbeat() {
    this.heartbeatTimer = setInterval(() => {
      if (this.connected) {
        this._sendMessage({
          type: 'heartbeat',
          clientId: this.config.clientId,
          timestamp: Date.now()
        });
      }
    }, this.config.heartbeatInterval);
  }

  /**
   * Stop heartbeat mechanism
   * @private
   */
  _stopHeartbeat() {
    if (this.heartbeatTimer) {
      clearInterval(this.heartbeatTimer);
      this.heartbeatTimer = null;
    }
  }

  /**
   * Setup default command handlers
   * @private
   */
  _setupDefaultHandlers() {
    this.onCommand('ping', () => {
      return { pong: true, clientId: this.config.clientId };
    });

    this.onCommand('getInfo', () => {
      return this.getClientInfo();
    });

    this.onCommand('disconnect', () => {
      this.disconnect();
      return { disconnected: true };
    });
  }

  /**
   * Dispatch an event
   * @private
   */
  _dispatchEvent(eventType, detail) {
    window.dispatchEvent(new CustomEvent(`commandserver-${eventType}`, { detail }));
  }

  /**
   * Generate a unique client ID
   * @private
   */
  _generateClientId() {
