/**
 * PentestModule.js
 * Comprehensive vulnerability scanner for web applications
 * Detects: XSS, CSRF, injection flaws, auth issues, CSP bypass, and more
 */

export class PentestModule {
  constructor(config = {}) {
    this.config = {
      verbose: config.verbose || false,
      includePassive: config.includePassive !== false,
      timeout: config.timeout || 5000,
      ...config
    };

    this.issues = [];
    this.results = {
      xss: [],
      csrf: [],
      injection: [],
      auth: [],
      csp: [],
      cors: [],
      headers: [],
      api: [],
      dom: [],
      crypto: []
    };
  }

  /**
   * Run comprehensive security analysis
   */
  async runFullAnalysis() {
    console.log('[PentestModule] Starting full security analysis...');
    const startTime = Date.now();

    await Promise.all([
      this.scanXSSVulnerabilities(),
      this.scanCSRFProtection(),
      this.scanInputValidation(),
      this.scanAuthenticationFlaws(),
      this.analyzeCSP(),
      this.analyzeCORS(),
      this.analyzeSecurityHeaders(),
      this.enumerateAPIs(),
      this.scanDOMVulnerabilities(),
      this.analyzeCryptography()
    ]);

    const duration = Date.now() - startTime;
    console.log(`[PentestModule] Analysis completed in ${duration}ms`);
    return this.generateReport();
  }

  /**
   * Scan for XSS vulnerabilities
   */
  async scanXSSVulnerabilities() {
    console.log('[PentestModule] Scanning for XSS vulnerabilities...');

    // Check for dangerous HTML operations
    const dangerousPatterns = [
      { pattern: /\.innerHTML\s*=/, desc: 'innerHTML assignment detected' },
      { pattern: /\.insertAdjacentHTML\s*\(/, desc: 'insertAdjacentHTML usage detected' },
      { pattern: /document\.write\s*\(/, desc: 'document.write() usage (XSS risk)' },
      { pattern: /eval\s*\(/, desc: 'eval() usage (code injection risk)' },
      { pattern: /Function\s*\(/, desc: 'Function constructor (code injection risk)' },
      { pattern: /setTimeout\s*\([^,]*\)/, desc: 'setTimeout with string argument' }
    ];

    const scriptElements = document.querySelectorAll('script');
    scriptElements.forEach(script => {
      const code = script.textContent;
      dangerousPatterns.forEach(({ pattern, desc }) => {
        if (pattern.test(code)) {
          this._addIssue('xss', 'high', desc, script.src || 'inline script', script);
        }
      });
    });

    // Check for unsanitized user input in DOM
    const inputs = document.querySelectorAll('input, textarea, [contenteditable]');
    inputs.forEach(input => {
      if (!input.getAttribute('data-sanitized') && !this._hasInputValidation(input)) {
        this._addIssue('xss', 'medium', 'Unsanitized input field detected', input.name || input.id, input);
      }
    });

    // Check for DOM-based XSS via dangerous sinks
    if (window.location.hash || window.location.search) {
      this._checkDOMBasedXSS();
    }

    return this.results.xss;
  }

  /**
   * Scan for CSRF protection
   */
  async scanCSRFProtection() {
    console.log('[PentestModule] Scanning CSRF protection...');

    // Check for CSRF tokens in forms
    const forms = document.querySelectorAll('form');
    forms.forEach(form => {
      const hasCSRFToken = form.querySelector('input[name*="csrf"], input[name*="token"], input[name*="nonce"]');
      const method = form.method?.toUpperCase() || 'GET';

      if ((method === 'POST' || method === 'PUT' || method === 'DELETE') && !hasCSRFToken) {
        this._addIssue('csrf', 'high', `${method} form missing CSRF token`, form.action || 'unknown', form);
      }
    });

    // Check for SameSite cookie attribute
    const cookies = document.cookie.split(';');
    const cookiesWithoutSameSite = cookies.filter(c => !c.toLowerCase().includes('samesite'));
    if (cookiesWithoutSameSite.length > 0) {
      this._addIssue('csrf', 'medium', `${cookiesWithoutSameSite.length} cookies missing SameSite attribute`);
    }

    return this.results.csrf;
  }

  /**
   * Scan for input validation issues
   */
  async scanInputValidation() {
    console.log('[PentestModule] Scanning input validation...');

    const inputs = document.querySelectorAll('input, textarea, select');
    inputs.forEach(input => {
      const validationAttributes = ['required', 'pattern', 'minlength', 'maxlength', 'type'];
      const hasValidation = validationAttributes.some(attr => input.hasAttribute(attr));

      if (!hasValidation && input.type !== 'hidden') {
        this._addIssue('injection', 'medium', 'No input validation attributes found', input.name || input.id, input);
      }

      // Check for SQL injection risk in specific patterns
      if (input.name?.toLowerCase().includes('search') || input.name?.toLowerCase().includes('query')) {
        this._addIssue('injection', 'high', 'Search/Query parameter without evident filtering', input.name, input);
      }
    });

    return this.results.injection;
  }

  /**
   * Scan for authentication flaws
   */
  async scanAuthenticationFlaws() {
    console.log('[PentestModule] Scanning authentication...');

    // Check for hardcoded credentials
    const bodyText = document.body.textContent;
    const credentialPatterns = [
      { pattern: /password\s*[:=]\s*["'][^"']*["']/gi, desc: 'Hardcoded password found' },
      { pattern: /api[_-]?key\s*[:=]\s*["'][^"']*["']/gi, desc: 'Hardcoded API key found' },
      { pattern: /secret\s*[:=]\s*["'][^"']*["']/gi, desc: 'Hardcoded secret found' }
    ];

    credentialPatterns.forEach(({ pattern, desc }) => {
      if (pattern.test(bodyText)) {
        this._addIssue('auth', 'critical', desc);
      }
    });

    // Check for session storage vulnerabilities
    if (sessionStorage.length > 0) {
      for (let i = 0; i < sessionStorage.length; i++) {
        const key = sessionStorage.key(i);
        if (key.toLowerCase().includes('token') || key.toLowerCase().includes('session')) {
          this._addIssue('auth', 'high', `Sensitive data in sessionStorage: ${key}`);
        }
      }
    }

    // Check for localStorage vulnerabilities
    if (localStorage.length > 0) {
      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (key.toLowerCase().includes('token') && key.toLowerCase().includes('auth')) {
          this._addIssue('auth', 'high', `Authentication token in localStorage: ${key}`);
        }
      }
    }

    // Check for missing or weak auth headers
    const links = document.querySelectorAll('a[href*="api"], a[href*="admin"]');
    links.forEach(link => {
      this._addIssue('auth', 'medium', 'Unprotected API/Admin endpoint', link.href, link);
    });

    return this.results.auth;
  }

  /**
   * Analyze Content Security Policy
   */
  async analyzeCSP() {
    console.log('[PentestModule] Analyzing CSP...');

    const cspHeader = document.querySelector('meta[http-equiv="Content-Security-Policy"]');

    if (!cspHeader) {
      this._addIssue('csp', 'high', 'No Content-Security-Policy header found');
    } else {
      const cspValue = cspHeader.getAttribute('content');

      if (cspValue.includes("'unsafe-inline'")) {
        this._addIssue('csp', 'high', "CSP allows 'unsafe-inline' scripts");
      }
      if (cspValue.includes("'unsafe-eval'")) {
        this._addIssue('csp', 'high', "CSP allows 'unsafe-eval'");
      }
      if (cspValue.includes('*')) {
        this._addIssue('csp', 'medium', 'CSP uses wildcard directive');
      }
    }

    return this.results.csp;
  }

  /**
   * Analyze CORS configuration
   */
  async analyzeCORS() {
    console.log('[PentestModule] Analyzing CORS...');

    try {
      const testUrl = `${window.location.origin}/test-cors`;
      const response = await fetch(testUrl, {
        method: 'OPTIONS',
        headers: {
          'Origin': window.location.origin,
          'Access-Control-Request-Method': 'GET'
        }
      }).catch(() => null);

      if (response && response.headers.get('Access-Control-Allow-Origin') === '*') {
        this._addIssue('cors', 'high', 'CORS allows all origins (*)');
      }
    } catch (error) {
      // CORS test failed - likely properly configured
    }

    return this.results.cors;
  }

  /**
   * Analyze security headers
   */
  async analyzeSecurityHeaders() {
    console.log('[PentestModule] Analyzing security headers...');

    const requiredHeaders = [
      { name: 'X-Frame-Options', severity: 'medium', description: 'Clickjacking protection' },
      { name: 'X-Content-Type-Options', severity: 'medium', description: 'MIME type sniffing protection' },
      { name: 'Strict-Transport-Security', severity: 'high', description: 'HTTPS enforcement' },
      { name: 'X-XSS-Protection', severity: 'low', description: 'XSS filter bypass' }
    ];

    requiredHeaders.forEach(header => {
      // Note: Response headers are not directly accessible from client-side JavaScript
      // This is a demonstration of what would be checked
      const metaTag = document.querySelector(`meta[http-equiv="${header.name}"]`);
      if (!metaTag) {
        this._addIssue('headers', header.severity, `Missing ${header.name} header (${header.description})`);
      }
    });

    return this.results.headers;
  }

  /**
   * Enumerate API endpoints
   */
  async enumerateAPIs() {
    console.log('[PentestModule] Enumerating API endpoints...');

    const endpoints = new Set();

    // Check fetch/XHR calls
    const scripts = document.querySelectorAll('script');
    scripts.forEach(script => {
      const code = script.textContent;
      const matches = code.match(/(?:fetch|XMLHttpRequest|axios|\.get|\.post)\s*\(\s*["'`]([^"'`]+)["'`]/g);
      if (matches) {
        matches.forEach(match => {
          const url = match.match(/["'`]([^"'`]+)["'`]/)[1];
          endpoints.add(url);
        });
      }
    });

    // Check form actions
    document.querySelectorAll('form').forEach(form => {
      if (form.action) endpoints.add(form.action);
    });

    // Check links
    document.querySelectorAll('a[href*="api"]').forEach(link => {
      if (link.href) endpoints.add(link.href);
    });

    endpoints.forEach(endpoint => {
      this._addIssue('api', 'low', 'API endpoint discovered', endpoint);
    });

    return Array.from(endpoints);
  }

  /**
   * Scan DOM for vulnerabilities
   */
  async scanDOMVulnerabilities() {
    console.log('[PentestModule] Scanning DOM structure...');

    // Check for debugging code
    const debugPatterns = [
      { pattern: /console\.log\s*\(/, desc: 'Console logging found' },
      { pattern: /debugger;/, desc: 'Debugger statement found' },
      { pattern: /alert\s*\(/, desc: 'Alert statements found' }
    ];

    document.querySelectorAll('script').forEach(script => {
      const code = script.textContent;
      debugPatterns.forEach(({ pattern, desc }) => {
        if (pattern.test(code)) {
          this._addIssue('dom', 'low', desc, script.src || 'inline');
        }
