    console.log('[PentestModule] Analyzing cryptography...');

    // Check for weak crypto implementations
    if (window.crypto && window.crypto.subtle) {
      const scripts = document.querySelectorAll('script');
      scripts.forEach(script => {
        const code = script.textContent;
        if (code.includes('Math.random()') && code.includes('crypto')) {
          this._addIssue('crypto', 'high', 'Mix of Math.random() with crypto operations (weak randomness)');
        }
      });
    } else {
      this._addIssue('crypto', 'medium', 'WebCrypto API not available');
    }

    return this.results.crypto;
  }

  /**
   * Check DOM-based XSS
   * @private
   */
  _checkDOMBasedXSS() {
    const hash = window.location.hash;
    const search = window.location.search;

    // Check if parameters are reflected in DOM
    const bodyText = document.body.innerHTML;
    if (hash && bodyText.includes(decodeURIComponent(hash))) {
      this._addIssue('xss', 'high', 'DOM-based XSS: Hash parameter reflected in DOM');
    }
    if (search && bodyText.includes(decodeURIComponent(search))) {
      this._addIssue('xss', 'high', 'DOM-based XSS: Query parameter reflected in DOM');
    }
  }

  /**
   * Check if input has validation
   * @private
   */
  _hasInputValidation(input) {
    return input.hasAttribute('required') ||
           input.hasAttribute('pattern') ||
           input.hasAttribute('minlength') ||
           input.hasAttribute('maxlength') ||
           (input.type && !['text', 'hidden'].includes(input.type));
  }

  /**
   * Add an issue to results
