            <p>For more information, visit: https://github.com/xosski/Avalanche</p>
        </div>
    </div>
</body>
</html>`;

    return html;
  }

  /**
   * Generate Markdown report
   */
  generateMarkdown() {
    let md = `# ${this.config.assessmentName}\n\n`;
    md += `**Assessment Report**\n\n`;

    md += `## Metadata\n\n`;
    md += `- **Generated**: ${this.data.metadata.timestamp}\n`;
    md += `- **URL**: ${this.data.metadata.url}\n`;
    md += `- **Assessor**: ${this.config.assessor}\n\n`;

