    const summary = this._calculateSummary();
    md += `## Summary\n\n`;
    md += `- **Total Issues**: ${summary.total}\n`;
    md += `- **Critical**: ${summary.critical}\n`;
    md += `- **High**: ${summary.high}\n`;
    md += `- **Medium**: ${summary.medium}\n`;
