        if (finding.detail) {
          md += `**Details**: \`${finding.detail}\`\n\n`;
        }
        md += `---\n\n`;
      });
    }

    // Recommendations
    if (this.data.recommendations.length > 0) {
      md += `## Recommendations\n\n`;
      this.data.recommendations.forEach((rec, idx) => {
        md += `${idx + 1}. ${rec}\n\n`;
      });
    }

    return md;
  }

  /**
   * Generate CSV report
   */
  generateCSV() {
    let csv = 'Severity,Category,Description,Detail,Timestamp\n';

    this.data.findings.forEach(finding => {
      csv += `"${finding.severity}","${finding.category}","${this._escapeCSV(finding.description)}","${this._escapeCSV(finding.detail)}","${finding.timestamp}"\n`;
    });

    return csv;
  }

  /**
   * Export report to file
   */
  exportToFile(format = 'json') {
    let content, filename, mimeType;

    switch (format.toLowerCase()) {
      case 'html':
        content = this.generateHTML();
        filename = `avalanche-report-${Date.now()}.html`;
        mimeType = 'text/html';
        break;
      case 'markdown':
      case 'md':
        content = this.generateMarkdown();
        filename = `avalanche-report-${Date.now()}.md`;
        mimeType = 'text/markdown';
        break;
      case 'csv':
        content = this.generateCSV();
        filename = `avalanche-report-${Date.now()}.csv`;
        mimeType = 'text/csv';
        break;
      case 'json':
      default:
        content = this.generateJSON();
        filename = `avalanche-report-${Date.now()}.json`;
        mimeType = 'application/json';
        break;
    }

    const blob = new Blob([content], { type: mimeType });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);

    return filename;
  }

  /**
   * Generate summary cards HTML
   * @private
   */
  _generateSummaryCards() {
    const summary = this._calculateSummary();
    return `
      <div class="summary-card critical">
        <div class="summary-number">${summary.critical}</div>
        <div class="summary-label">Critical</div>
      </div>
      <div class="summary-card high">
        <div class="summary-number">${summary.high}</div>
        <div class="summary-label">High</div>
      </div>
      <div class="summary-card medium">
        <div class="summary-number">${summary.medium}</div>
        <div class="summary-label">Medium</div>
      </div>
      <div class="summary-card low">
        <div class="summary-number">${summary.low}</div>
        <div class="summary-label">Low</div>
      </div>
    `;
  }

  /**
   * Generate findings HTML
   * @private
   */
  _generateFindingsHTML() {
    if (this.data.findings.length === 0) {
      return '<div class="no-findings">No findings detected</div>';
    }

    return this.data.findings
      .sort((a, b) => {
        const severityOrder = { critical: 0, high: 1, medium: 2, low: 3 };
        return severityOrder[a.severity] - severityOrder[b.severity];
      })
      .map(finding => `
        <div class="finding ${finding.severity}">
          <div class="finding-header">
            <div class="finding-title">${this._escapeHtml(finding.description)}</div>
            <span class="finding-severity ${finding.severity}">${finding.severity}</span>
          </div>
          <div class="finding-description"><strong>Category:</strong> ${this._escapeHtml(finding.category)}</div>
          ${finding.detail ? `<div class="finding-detail">${this._escapeHtml(finding.detail)}</div>` : ''}
          <div class="finding-description"><small>Detected: ${finding.timestamp}</small></div>
        </div>
      `)
      .join('');
  }

  /**
   * Generate recommendations HTML
   * @private
   */
  _generateRecommendationsHTML() {
    return this.data.recommendations
      .map(rec => `
        <div class="recommendation">
          <div class="recommendation-text">• ${this._escapeHtml(rec)}</div>
        </div>
      `)
      .join('');
  }

  /**
   * Calculate summary statistics
   * @private
   */
  _calculateSummary() {
    return {
      total: this.data.findings.length,
      critical: this.data.findings.filter(f => f.severity === 'critical').length,
      high: this.data.findings.filter(f => f.severity === 'high').length,
      medium: this.data.findings.filter(f => f.severity === 'medium').length,
      low: this.data.findings.filter(f => f.severity === 'low').length
    };
  }

  /**
   * Escape HTML special characters
   * @private
   */
  _escapeHtml(text) {
    const map = {
      '&': '&amp;',
      '<': '&lt;',
      '>': '&gt;',
      '"': '&quot;',
      "'": '&#039;'
    };
    return String(text).replace(/[&<>"']/g, m => map[m]);
  }

  /**
   * Escape CSV special characters
   * @private
   */
  _escapeCSV(text) {
    return String(text).replace(/"/g, '""');
  }
}

export default ReportingEngine;

