/**
 * ReportingEngine.js
 * Multi-format report generation (JSON, HTML, CSV, Markdown)
 * Exports security findings and telemetry data
 */

export class ReportingEngine {
  constructor(config = {}) {
    this.config = {
      companyName: config.companyName || 'Security Assessment',
      assessmentName: config.assessmentName || 'Avalanche Security Scan',
      assessor: config.assessor || 'Automated Scan',
      ...config
    };

    this.data = {
      metadata: {
        timestamp: new Date().toISOString(),
        url: window.location.href,
        userAgent: navigator.userAgent
      },
      findings: [],
      telemetry: {},
      recommendations: []
    };
  }

  /**
   * Add findings to the report
   */
  addFindings(findings) {
    if (Array.isArray(findings)) {
      this.data.findings.push(...findings);
    } else {
      this.data.findings.push(findings);
    }
  }

  /**
   * Add telemetry data
   */
  addTelemetry(key, value) {
    this.data.telemetry[key] = value;
  }

  /**
   * Add remediation recommendations
   */
  addRecommendations(recommendations) {
    if (Array.isArray(recommendations)) {
      this.data.recommendations.push(...recommendations);
    } else {
      this.data.recommendations.push(recommendations);
