            <span class="finding-severity ${finding.severity}">${finding.severity}</span>
          </div>
          <div class="finding-description"><strong>Category:</strong> ${this._escapeHtml(finding.category)}</div>
          ${finding.detail ? `<div class="finding-detail">${this._escapeHtml(finding.detail)}</div>` : ''}
          <div class="finding-description"><small>Detected: ${finding.timestamp}</small></div>
        </div>
      `)
      .join('');
  }

  /**
   * Generate recommendations HTML
   * @private
   */
  _generateRecommendationsHTML() {
    return this.data.recommendations
      .map(rec => `
        <div class="recommendation">
          <div class="recommendation-text">• ${this._escapeHtml(rec)}</div>
        </div>
      `)
      .join('');
  }

  /**
   * Calculate summary statistics
   * @private
   */
  _calculateSummary() {
    return {
      total: this.data.findings.length,
      critical: this.data.findings.filter(f => f.severity === 'critical').length,
      high: this.data.findings.filter(f => f.severity === 'high').length,
      medium: this.data.findings.filter(f => f.severity === 'medium').length,
      low: this.data.findings.filter(f => f.severity === 'low').length
    };
  }

  /**
   * Escape HTML special characters
