      .map(([name, value]) => `<input type="hidden" name="${name}" value="${value}">`)
      .join('');

    return `
      <form action="${formAction}" method="${formMethod}" style="display:none;">
        ${fieldInputs}
        <input type="submit">
      </form>
      <script>
        document.querySelector('form').submit();
      </script>
    `;
  }

  /**
   * List all available payload categories
   */
  static getCategories() {
    return [
      'XSS',
      'CSRF',
      'INJECTION',
      'AUTHENTICATION',
      'HEADERS',
      'FUZZING',
      'WEBSOCKET'
    ];
  }

  /**
   * List all types in a category
   */
  static getTypesInCategory(category) {
    const categoryPayloads = this[category.toUpperCase()];
    return categoryPayloads ? Object.keys(categoryPayloads) : [];
  }

  /**
   * Count total payloads
   */
  static getTotalPayloadCount() {
    let total = 0;
    this.getCategories().forEach(cat => {
      const categoryPayloads = this[cat];
      Object.values(categoryPayloads).forEach(typePayloads => {
        total += Array.isArray(typePayloads) ? typePayloads.length : 0;
      });
    });
    return total;
  }

  /**
   * Export payloads as JSON
   */
  static exportAsJSON() {
    const payload = {};
    this.getCategories().forEach(cat => {
      payload[cat] = this[cat];
    });
    return JSON.stringify(payload, null, 2);
  }
}

