/**
 * Integration.js
 * Unified interface for all Avalanche modules
 * Coordinates CommandServer, PentestModule, ReportingEngine, and PayloadTemplates
 */

import CommandServer from './CommandServer.js';
import { PentestModule } from './PentestModule.js';
import { ReportingEngine } from './ReportingEngine.js';
import { PayloadTemplates } from './PayloadTemplates.js';

export class AvalancheFramework {
  constructor(config = {}) {
    this.config = {
      commandServerUrl: config.commandServerUrl || 'ws://localhost:8080',
      autoConnect: config.autoConnect === false ? false : true,
      enablePentesting: config.enablePentesting !== false ? true : false,
      enableReporting: config.enableReporting !== false ? true : false,
      ...config
    };

    // Initialize modules
    this.commandServer = new CommandServer({
      serverUrl: this.config.commandServerUrl,
      clientId: config.clientId
    });

    this.pentest = new PentestModule({
      verbose: config.verbose || false,
      timeout: config.timeout || 5000
    });

    this.reporting = new ReportingEngine({
      companyName: config.companyName,
      assessmentName: config.assessmentName,
      assessor: config.assessor
    });

    this.payloads = PayloadTemplates;

    this.state = {
      initialized: false,
      connected: false,
      scanRunning: false,
      lastScanResults: null
    };

    this._setupEventListeners();
  }

  /**
   * Initialize the framework
   */
  async initialize() {
    console.log('[Avalanche] Initializing framework...');

    try {
      // Register command handlers
      this._registerCommandHandlers();

      // Auto-connect if enabled
      if (this.config.autoConnect) {
        await this.connect();
      }

      this.state.initialized = true;
      console.log('[Avalanche] Framework initialized');
      this._dispatchEvent('initialized');

      return true;
    } catch (error) {
      console.error('[Avalanche] Initialization failed:', error);
      return false;
    }
  }

  /**
   * Connect to command server
   */
  async connect() {
    try {
      await this.commandServer.connect();
      this.state.connected = true;
      console.log('[Avalanche] Connected to command server');
      this._dispatchEvent('connected');
      return true;
    } catch (error) {
      console.error('[Avalanche] Connection failed:', error);
      this.state.connected = false;
      return false;
    }
  }

  /**
   * Disconnect from command server
   */
  disconnect() {
    this.commandServer.disconnect();
    this.state.connected = false;
    this._dispatchEvent('disconnected');
  }

  /**
   * Run full security assessment
   */
  async runSecurityAssessment() {
    if (this.state.scanRunning) {
      console.warn('[Avalanche] Scan already in progress');
      return null;
    }

    this.state.scanRunning = true;
    console.log('[Avalanche] Starting security assessment...');
    this._dispatchEvent('scan-started');

    try {
      const results = await this.pentest.runFullAnalysis();

      // Add findings to report
      this.reporting.addFindings(results.issues);

      // Add remediation recommendations
      this._addRecommendations(results);

      // Send telemetry to command server
      if (this.state.connected) {
        await this.commandServer.sendCommand('assessmentComplete', {
          url: window.location.href,
          timestamp: Date.now(),
          issueCount: results.summary.totalIssues,
          criticalCount: results.summary.criticalIssues
        });
      }

      this.state.lastScanResults = results;
      this.state.scanRunning = false;
      console.log('[Avalanche] Assessment completed');
      this._dispatchEvent('scan-completed', results);

      return results;
    } catch (error) {
      console.error('[Avalanche] Assessment failed:', error);
      this.state.scanRunning = false;
      this._dispatchEvent('scan-failed', error);
      return null;
    }
  }

  /**
   * Export security report
   */
  exportReport(format = 'html') {
    if (!this.state.lastScanResults) {
      console.warn('[Avalanche] No scan results to export');
      return null;
    }

    const filename = this.reporting.exportToFile(format);
    console.log(`[Avalanche] Report exported: ${filename}`);
    this._dispatchEvent('report-exported', { filename, format });

    return filename;
  }

  /**
   * Get scan results
   */
  getResults(category = null) {
    if (!this.state.lastScanResults) {
      return null;
    }

    if (category) {
      return this.state.lastScanResults.results[category] || [];
    }

    return this.state.lastScanResults;
  }

  /**
   * Test specific vulnerability
   */
  async testVulnerability(type, target = null) {
    console.log(`[Avalanche] Testing ${type}...`);

    const testTarget = target || document.body;
    let result = null;

    switch (type.toLowerCase()) {
      case 'xss':
        result = this.payloads.testXSSPayloads(testTarget);
        break;
      case 'csrf':
        result = this.pentest.scanCSRFProtection();
        break;
      case 'injection':
        result = this.pentest.scanInputValidation();
        break;
      case 'auth':
        result = this.pentest.scanAuthenticationFlaws();
        break;
      default:
        console.warn(`[Avalanche] Unknown vulnerability type: ${type}`);
        return null;
    }

    return result;
  }

  /**
   * Inject payload for testing
   */
  injectPayload(payloadType, payloadName, target = null) {
    const payload = this.payloads.getRandomPayload(payloadType, payloadName);
    if (!payload) {
      console.warn(`[Avalanche] Payload not found: ${payloadType}/${payloadName}`);
      return null;
    }

    if (target) {
      this.payloads.injectIntoElement(target, payload);
    } else {
      this.payloads.injectIntoAllInputs(payload);
    }

    console.log(`[Avalanche] Payload injected: ${payloadType}/${payloadName}`);
    this._dispatchEvent('payload-injected', { payloadType, payloadName });

    return payload;
  }

  /**
   * Get telemetry data
   */
  getTelemetry() {
    return {
      initialized: this.state.initialized,
      connected: this.state.connected,
      scanRunning: this.state.scanRunning,
      clientInfo: this.commandServer.getClientInfo(),
      lastScan: this.state.lastScanResults?.summary || null
    };
  }

  /**
   * Register command handlers
   * @private
   */
  _registerCommandHandlers() {
    // runScan command
    this.commandServer.onCommand('runScan', async (payload) => {
      const results = await this.runSecurityAssessment();
      return results?.summary || null;
    });

    // exportReport command
    this.commandServer.onCommand('exportReport', (payload) => {
      const format = payload.format || 'html';
      return this.exportReport(format);
    });

    // getTelemetry command
    this.commandServer.onCommand('getTelemetry', () => {
      return this.getTelemetry();
    });

    // injectPayload command
    this.commandServer.onCommand('injectPayload', (payload) => {
      return this.injectPayload(payload.type, payload.name);
    });

    // getResults command
    this.commandServer.onCommand('getResults', (payload) => {
      return this.getResults(payload.category);
    });

    // getPayloads command
    this.commandServer.onCommand('getPayloads', (payload) => {
      return this.payloads.getAll(payload.category, payload.type);
    });
  }

  /**
   * Add remediation recommendations
   * @private
   */
  _addRecommendations(results) {
    const recommendations = [];

    if (results.summary.criticalIssues > 0) {
      recommendations.push('Immediately address all critical issues before deploying to production');
      recommendations.push('Conduct a code review focusing on security-critical components');
    }

    if (results.results.xss.length > 0) {
      recommendations.push('Implement Content Security Policy (CSP) headers to mitigate XSS attacks');
      recommendations.push('Use templating engines with automatic HTML escaping');
      recommendations.push('Apply input validation and output encoding consistently');
    }

    if (results.results.csrf.length > 0) {
      recommendations.push('Implement CSRF tokens for all state-changing operations');
      recommendations.push('Set SameSite attribute on all cookies');
      recommendations.push('Validate Origin and Referer headers');
    }

    if (results.results.auth.length > 0) {
      recommendations.push('Never store sensitive credentials in client-side storage');
      recommendations.push('Use secure HTTP-only cookies for session tokens');
      recommendations.push('Implement proper authentication and authorization checks');
    }

    if (results.results.csp.length > 0) {
      recommendations.push('Define a strict Content Security Policy');
      recommendations.push('Avoid inline scripts and styles');
      recommendations.push('Use nonces or hashes for unavoidable inline content');
    }

    this.reporting.addRecommendations([...new Set(recommendations)]);
  }

  /**
   * Setup event listeners
   * @private
   */
  _setupEventListeners() {
    window.addEventListener('commandserver-message', (e) => {
      console.log('[Avalanche] Message received:', e.detail);
    });

    window.addEventListener('commandserver-broadcast', (e) => {
      console.log('[Avalanche] Broadcast received:', e.detail);
    });
  }

  /**
   * Dispatch custom event
   * @private
   */
  _dispatchEvent(eventType, detail = null) {
    window.dispatchEvent(new CustomEvent(`avalanche-${eventType}`, { detail }));
  }

  /**
   * Get framework status
   */
  getStatus() {
    return {
      state: this.state,
      commandServer: {
        connected: this.commandServer.connected,
        clientId: this.commandServer.config.clientId
      },
      modules: {
        pentest: 'available',
        reporting: 'available',
        payloads: `${this.payloads.getTotalPayloadCount()} payloads loaded`
      }
    };
  }
}

// Auto-initialize on load
if (typeof window !== 'undefined') {
  window.AvalancheFramework = AvalancheFramework;

  // Expose for console access
  if (!window.avalanche) {
    window.avalanche = null;
  }

  document.addEventListener('DOMContentLoaded', () => {
    console.log('[Avalanche] Ready to initialize. Run: window.avalanche = new AvalancheFramework()');
  });
}

export default AvalancheFramework;

