  try {
    const result = await fetch(payload.url, {
      method: payload.method || 'GET',
      headers: payload.headers,
      body: payload.body
    }).then(r => r.json());

    return { success: true, result };
  } catch (error) {
    return { success: false, error: error.message };
  }
});

// Server sends command
